
USE vacation_brain;

-- Vacation Brain v1.16: sample-data showcase + destination research/report catalog.
ALTER TABLE users ADD COLUMN is_sample TINYINT(1) NOT NULL DEFAULT 0 AFTER status, ADD KEY idx_users_sample_status (is_sample,status);
ALTER TABLE destination_catalog ADD COLUMN is_sample TINYINT(1) NOT NULL DEFAULT 0 AFTER status, ADD COLUMN latitude DECIMAL(10,7) NULL AFTER country, ADD COLUMN longitude DECIMAL(10,7) NULL AFTER latitude, ADD COLUMN last_researched_at DATETIME NULL AFTER metadata_json, ADD KEY idx_destination_catalog_sample (is_sample,status,featured,sort_order);
ALTER TABLE merch_catalog_products ADD COLUMN is_sample TINYINT(1) NOT NULL DEFAULT 0 AFTER status, ADD KEY idx_merch_catalog_sample (is_sample,status,featured,sort_order);
ALTER TABLE places ADD COLUMN is_sample TINYINT(1) NOT NULL DEFAULT 0 AFTER active, ADD KEY idx_places_sample (is_sample,active,place_type,city);

CREATE TABLE destination_reports (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  destination_catalog_id BIGINT UNSIGNED NULL,
  requested_by BIGINT UNSIGNED NULL,
  query_text VARCHAR(500) NOT NULL,
  normalized_location VARCHAR(255) NULL,
  travel_start_date DATE NULL,
  travel_end_date DATE NULL,
  status VARCHAR(32) NOT NULL DEFAULT 'ready',
  research_mode VARCHAR(32) NOT NULL DEFAULT 'web_ai',
  provider VARCHAR(40) NULL,
  model_name VARCHAR(160) NULL,
  is_sample TINYINT(1) NOT NULL DEFAULT 0,
  summary_text LONGTEXT NULL,
  weather_history_json JSON NULL,
  weather_forecast_json JSON NULL,
  lodging_json JSON NULL,
  day_trips_json JSON NULL,
  restaurants_json JSON NULL,
  shows_json JSON NULL,
  photo_gallery_json JSON NULL,
  sources_json JSON NULL,
  raw_response_json LONGTEXT NULL,
  generated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at DATETIME NULL,
  PRIMARY KEY (id),
  KEY idx_destination_reports_destination (destination_catalog_id,generated_at),
  KEY idx_destination_reports_user (requested_by,generated_at),
  KEY idx_destination_reports_sample (is_sample,status,generated_at),
  CONSTRAINT fk_destination_reports_catalog FOREIGN KEY (destination_catalog_id) REFERENCES destination_catalog(id) ON DELETE SET NULL,
  CONSTRAINT fk_destination_reports_user FOREIGN KEY (requested_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE destination_report_sources (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  report_id BIGINT UNSIGNED NOT NULL,
  source_type VARCHAR(64) NOT NULL DEFAULT 'web',
  title VARCHAR(500) NULL,
  publisher VARCHAR(255) NULL,
  url VARCHAR(1500) NOT NULL,
  snippet TEXT NULL,
  published_at DATETIME NULL,
  accessed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_destination_report_sources (report_id,source_type),
  CONSTRAINT fk_destination_report_sources_report FOREIGN KEY (report_id) REFERENCES destination_reports(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE destination_research_entities (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  report_id BIGINT UNSIGNED NOT NULL,
  destination_catalog_id BIGINT UNSIGNED NULL,
  entity_type VARCHAR(64) NOT NULL,
  name VARCHAR(300) NOT NULL,
  summary TEXT NULL,
  address VARCHAR(500) NULL,
  website_url VARCHAR(1500) NULL,
  booking_url VARCHAR(1500) NULL,
  source_url VARCHAR(1500) NULL,
  rating DECIMAL(4,2) NULL,
  review_count INT UNSIGNED NULL,
  price_text VARCHAR(120) NULL,
  starts_at DATETIME NULL,
  ends_at DATETIME NULL,
  metadata_json JSON NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_destination_research_entity (destination_catalog_id,entity_type,name),
  KEY idx_destination_research_report (report_id,entity_type),
  CONSTRAINT fk_destination_research_report FOREIGN KEY (report_id) REFERENCES destination_reports(id) ON DELETE CASCADE,
  CONSTRAINT fk_destination_research_catalog FOREIGN KEY (destination_catalog_id) REFERENCES destination_catalog(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE destination_gallery_images (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  destination_catalog_id BIGINT UNSIGNED NOT NULL,
  report_id BIGINT UNSIGNED NULL,
  image_url VARCHAR(1500) NOT NULL,
  caption VARCHAR(300) NULL,
  source_url VARCHAR(1500) NULL,
  source_name VARCHAR(255) NULL,
  is_sample TINYINT(1) NOT NULL DEFAULT 0,
  sort_order INT NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_destination_gallery (destination_catalog_id,sort_order,id),
  CONSTRAINT fk_destination_gallery_catalog FOREIGN KEY (destination_catalog_id) REFERENCES destination_catalog(id) ON DELETE CASCADE,
  CONSTRAINT fk_destination_gallery_report FOREIGN KEY (report_id) REFERENCES destination_reports(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO site_settings (setting_key,setting_value,setting_group) VALUES
