-- Normalize the sample destination reports into the same structured shape used by live AI research.
UPDATE destination_reports dr
JOIN destination_catalog dc ON dc.id=dr.destination_catalog_id
SET
  dr.weather_history_json=JSON_OBJECT(
    'summary',CONCAT('Sample historical weather overview for ',dc.name,'. Refresh with live AI research for sourced climate normals.'),
    'seasonal_notes',JSON_ARRAY(
      JSON_OBJECT('period','Peak season','conditions','Generally favorable conditions for the destination.','typical_high',NULL,'typical_low',NULL,'rain_notes','Demo data only.','source_url',NULL),
      JSON_OBJECT('period','Shoulder season','conditions','Often a useful balance of weather, crowds and price.','typical_high',NULL,'typical_low',NULL,'rain_notes','Demo data only.','source_url',NULL)
    )
  ),
  dr.weather_forecast_json=JSON_OBJECT(
    'summary','Sample forecast placeholder. Refresh this report for date-specific current weather.','as_of',NULL,'days',JSON_ARRAY()
  ),
  dr.lodging_json=JSON_OBJECT(
    'summary',CONCAT('Sample lodging mix for ',dc.name,'. Live research will replace these cards with sourced options.'),
    'hotels',JSON_ARRAY(JSON_OBJECT('name',CONCAT(dc.name,' Sample Hotel'),'area',dc.city,'summary','A representative hotel card for layout and catalog testing.','price_text','$$$','rating',4.6,'review_count',640,'website_url',NULL,'booking_url',NULL,'source_url',NULL)),
    'airbnb',JSON_ARRAY(JSON_OBJECT('name',CONCAT(dc.name,' Sample Airbnb'),'area',dc.city,'summary','Representative vacation-rental card. Live research does not claim availability unless verified.','price_text','$$','booking_url',NULL,'source_url',NULL)),
    'vrbo',JSON_ARRAY(JSON_OBJECT('name',CONCAT(dc.name,' Sample Vrbo'),'area',dc.city,'summary','Representative whole-home rental card for the report layout.','price_text','$$$','booking_url',NULL,'source_url',NULL))
  ),
  dr.day_trips_json=JSON_OBJECT(
    'day_trips',JSON_ARRAY(
      JSON_OBJECT('name',CONCAT(dc.name,' signature day trip'),'summary','A representative excursion used to demonstrate saved destination research.','distance','Half day','price_text','$$','source_url',NULL),
      JSON_OBJECT('name','Do less on purpose','summary','A lower-effort option because Vacation Brain recognizes that vacation is not a productivity contest.','distance','Nearby','price_text','$','source_url',NULL)
    ),
    'entertainment',JSON_ARRAY(JSON_OBJECT('name',CONCAT(dc.name,' evening option'),'summary','Sample entertainment card. Refresh for current venues, shows and schedules.','category','Entertainment','source_url',NULL))
  )
WHERE dr.is_sample=1;

-- Catalog representative sample entities so Admin can see the same normalization used by live research.
INSERT INTO destination_research_entities
(report_id,destination_catalog_id,entity_type,name,summary,address,rating,review_count,price_text,metadata_json)
SELECT dr.id,dc.id,'hotel',CONCAT(dc.name,' Sample Hotel'),'Representative sample lodging entity.',dc.city,4.60,640,'$$$',JSON_OBJECT('sample',true)
FROM destination_reports dr JOIN destination_catalog dc ON dc.id=dr.destination_catalog_id
WHERE dr.is_sample=1 AND NOT EXISTS (
  SELECT 1 FROM destination_research_entities e WHERE e.report_id=dr.id AND e.entity_type='hotel' AND e.name=CONCAT(dc.name,' Sample Hotel')
);

INSERT INTO destination_research_entities
(report_id,destination_catalog_id,entity_type,name,summary,address,rating,review_count,price_text,metadata_json)
SELECT dr.id,dc.id,'restaurant',CONCAT(dc.name,' Local Favorite'),'Representative sample restaurant entity. Refresh the report for current review-grounded recommendations.',dc.city,4.70,850,'$$',JSON_OBJECT('sample',true)
FROM destination_reports dr JOIN destination_catalog dc ON dc.id=dr.destination_catalog_id
WHERE dr.is_sample=1 AND NOT EXISTS (
  SELECT 1 FROM destination_research_entities e WHERE e.report_id=dr.id AND e.entity_type='restaurant' AND e.name=CONCAT(dc.name,' Local Favorite')
);

INSERT INTO places (name,place_type,description,city,region,country,latitude,longitude,active,is_sample,metadata_json)
SELECT CONCAT(dc.name,' Sample Hotel'),'hotel','Sample lodging catalog entity generated for the Vacation Brain demo dataset.',dc.city,dc.region,dc.country,dc.latitude,dc.longitude,1,1,JSON_OBJECT('sample',true,'destination_catalog_id',dc.id)
FROM destination_catalog dc
WHERE dc.is_sample=1 AND dc.slug IN ('santorini','kyoto','tulum','aspen','bali','amalfi-coast','maui','paris','sedona','costa-rica')
AND NOT EXISTS (SELECT 1 FROM places p WHERE p.name=CONCAT(dc.name,' Sample Hotel') AND p.place_type='hotel' AND COALESCE(p.city,'')=COALESCE(dc.city,''));

INSERT INTO places (name,place_type,description,city,region,country,latitude,longitude,active,is_sample,metadata_json)
SELECT CONCAT(dc.name,' Local Favorite'),'restaurant','Sample restaurant catalog entity. Live destination research will add sourced local businesses later.',dc.city,dc.region,dc.country,dc.latitude,dc.longitude,1,1,JSON_OBJECT('sample',true,'destination_catalog_id',dc.id)
FROM destination_catalog dc
WHERE dc.is_sample=1 AND dc.slug IN ('santorini','kyoto','tulum','aspen','bali','amalfi-coast','maui','paris','sedona','costa-rica')
AND NOT EXISTS (SELECT 1 FROM places p WHERE p.name=CONCAT(dc.name,' Local Favorite') AND p.place_type='restaurant' AND COALESCE(p.city,'')=COALESCE(dc.city,''));

